import{j as e}from"./index-Dq5t7Moj.js";import{L as a}from"./vendor-react-BmIvSP4v.js";import"./vendor-icons-DnDMfZhy.js";const o=[{q:"What is the adoption process?",a:"Submit an application, we review it and reach out, you meet the cat, and if it's a match you sign the adoption agreement and pay the fee. Most adoptions wrap up within about a week."},{q:"What is the adoption fee?",a:"$150, due at adoption. It covers spay or neuter, age-appropriate vaccines, deworming, microchip, and the care that got your cat healthy. It's an adoption fee, not a purchase price, and it's a fraction of what the same vetting costs out of pocket."},{q:"Do I have to keep my cat indoors?",a:"Yes. Every adoption is indoor-only. Catios and supervised harness time are wonderful; free roaming is not. Indoor cats live longer, healthier lives, and it's a condition of every adoption."},{q:"What about declawing?",a:"Never. Declawing is an amputation, not a nail trim, and it's illegal in California. Our adoption agreement prohibits it anywhere."},{q:"Can I adopt if I rent?",a:"Yes, as long as your lease or landlord allows cats. Confirming that is your responsibility, and we're glad to help with documentation."},{q:"What do I know about my cat's health?",a:"Everything we know, you know: full medical records, history, and quirks. Rescue cats come from unknown backgrounds, so we can't guarantee the future, but we never hide the past."},{q:"Why are some cats adopted in pairs?",a:"Cats under a year old go home in pairs, unless you already have a cat or kitten for them to bond with. Young cats need a same-age buddy to stay socialized and burn off energy; a solo kitten with no friend often turns into a nippy, climb-the-curtains handful. A resident cat counts. A bonded dog might count too, case by case, if you have had a cat before that the dog was close with. It also depends on the cat, and we will always tell you which is which."},{q:"What if it doesn't work out?",a:"Bring the cat back to us. Every adoption comes with a lifetime return promise: any reason, any time, no judgment. Please never rehome a Pawsitive cat on your own, and never surrender one to a shelter. They always have a home with us."},{q:"Can I adopt as a gift or surprise?",a:"No. Cats are adopted to the household they'll live in, so bring the actual adopter through the process. We promise it's painless."},{q:"Do you adopt outside the area?",a:"We prioritize homes in the Inland Empire and greater Southern California. Out-of-area applications are considered case by case."}];function r(){return e.jsxs("div",{className:"bg-white",children:[e.jsx("section",{className:"border-b border-slate-100 bg-white",children:e.jsxs("div",{className:"mx-auto max-w-7xl px-6 py-12 lg:px-8",children:[e.jsx("h1",{className:"text-4xl font-extrabold tracking-tight text-brand lg:text-5xl",children:"Adoption Process"}),e.jsx("p",{className:"mt-4 max-w-3xl text-lg leading-relaxed text-slate-600",children:"Every cat here lives with a foster who knows them: their quirks, their favorite spot, their whole personality. Ask us anything."})]})}),e.jsxs("div",{className:"mx-auto max-w-7xl px-6 py-12 lg:px-8",children:[e.jsxs("div",{className:"mx-auto max-w-3xl space-y-6",children:[e.jsx("h2",{className:"text-2xl font-bold text-slate-900",children:"Adoption FAQ"}),o.map(t=>e.jsxs("div",{className:"rounded-xl border border-slate-100 bg-white p-6 shadow-sm",children:[e.jsx("h3",{className:"font-bold text-slate-900",children:t.q}),e.jsx("p",{className:"mt-2 text-sm leading-relaxed text-slate-600",children:t.a})]},t.q))]}),e.jsx("section",{className:"mx-auto mt-12 max-w-4xl",children:e.jsxs("div",{className:"flex flex-col items-center gap-6 rounded-2xl border border-brand/40 bg-white px-8 py-6 text-center sm:flex-row sm:items-start sm:text-left",children:[e.jsxs("div",{className:"min-w-0 flex-1",children:[e.jsx("h2",{className:"text-xl font-bold text-brand",children:"Adoption Application"}),e.jsx("p",{className:"mt-1.5 text-sm leading-relaxed text-slate-600",children:"Ready to adopt? Submit an application and our team will be in touch to help you meet your new best friend."})]}),e.jsx("div",{className:"mt-2 w-full shrink-0 sm:mt-0 sm:w-auto",children:e.jsx(a,{to:"/adopt/apply",className:"inline-flex w-full items-center justify-center whitespace-nowrap rounded-xl bg-brand px-7 py-4 text-base font-semibold text-white shadow-sm transition hover:bg-brand-dark sm:w-auto",children:"Apply to Adopt"})})]})})]})]})}export{r as default};
